/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Extension of <c>NumberSeqModuleVendor</c> to add METCash functionality
/// </summary>
[ExtensionOf(classStr(NumberSeqModuleVendor))]
final class METNumberSeqModuleVendorClass_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Loads Vendor module adding a new Number Sequence for ALM Supplier
    /// Volumetric Rebates
    /// </summary>
    protected void loadModule()
    {
        NumberSeqDatatype datatype = NumberSeqDatatype::construct();
        
        next loadModule();

        datatype.parmDatatypeId(extendedTypeNum(METALMSupplierVolumetricRebateNumber));
        datatype.parmReferenceLabel("@MET:ALMSVRNumber");
        datatype.parmReferenceHelp(literalStr("@MET:ALMSVRreferenceHelp"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardFetchAheadQty(10);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmWizardHighest(999999);
        datatype.parmSortField(42);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);

        /// <summary>
        /// Loads Vendor module adding a new Number Sequence for CBCT Number
        /// Chargeback chargeThrough
        /// </summary>

        datatype.parmDatatypeId(extendedTypeNum(METCBCTNumber));
        datatype.parmReferenceLabel("@MET:ChargeThroughInvoiceNumber");
        datatype.parmReferenceHelp(literalStr("@MET:ChargeThroughInvoiceNumberReferenceHelp"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardFetchAheadQty(10);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmWizardHighest(999999);
        datatype.parmSortField(43);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);

        /// <summary>
        /// Loads Vendor module adding a new Number Sequence for Vendor return invoice number
        /// </summary>
        
        datatype.parmDatatypeId(extendedTypeNum(METVendReturnInvoiceNumber));
        datatype.parmReferenceLabel("@MET:VendRetInvNum");
        datatype.parmReferenceHelp(literalStr("@MET:PendingVendRetInv"));
        datatype.parmWizardIsContinuous(true);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardFetchAheadQty(10);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmWizardHighest(999999);
        datatype.parmSortField(44);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);

        /// <summary>
        /// Loads Vendor module adding a new Number Sequence for Vendor return invoice number
        /// </summary>
        
        datatype.parmDatatypeId(extendedTypeNum(METCPNumber));
        datatype.parmReferenceLabel("@MET:CPNumber");
        datatype.parmReferenceHelp(literalStr("@MET:CPNumHelp"));
        datatype.parmWizardIsContinuous(true);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardFetchAheadQty(10);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmWizardHighest(999999);
        datatype.parmSortField(44);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);
    }
